using namespace MediaEngine;
int main(int argc,char **argv) {
 QCoreApplication app(argc,argv); auto args=app.arguments(); if(args.size()!=3) return 2;
 const QFileInfo before(args[1]); QFile f(args[1]); if(!f.open(QIODevice::ReadOnly|QIODevice::Unbuffered)) return 3;
 Cancellation cancel; auto snap=QSharedPointer<SourceSnapshot>::create(); snap->path=args[1]; snap->source=MetadataSource::Avb;
 auto source=QSharedPointer<ParsedSource>::create(AvbReader{}.read(f,{snap,cancel}));
 AvbReferenceIndex index({source},cancel); ObjectHandle seq=args[2].toULongLong();
 auto result=index.resolveReferences({{0,AvbSelection::Kind::SelectedSequences,{seq}}},cancel);
 QSet<ObjectHandle> reachable; for(auto root:result.roots)reachable.insert(root.objectHandle);
 QJsonArray edges,objects,media,issues,sequences;
 for(auto edge:result.edges) { reachable.insert(edge.origin.objectHandle); reachable.insert(edge.target.objectHandle);
  const auto &r=source->relationships[edge.relationshipIndex]; edges.append(QJsonObject{{"origin",double(edge.origin.objectHandle)},{"target",double(edge.target.objectHandle)},{"field",r.locator.name}}); }
 for(const auto &o:source->objects) if(reachable.contains(o.handle)) {
  QJsonObject fields;
  for(const auto &p:o.properties) if(p.state==PropertyReadState::Present) {
   const auto &n=p.locator.name;
   if(n.startsWith("Component.")||n.startsWith("Clip.")||n.startsWith("SourceClip.")||n.startsWith("TrackGroup.")||n.startsWith("Composition.")||n.startsWith("Selector.")||n.startsWith("Sequence.")||n.startsWith("MediaLocator.")||n.startsWith("AudioSuitePlugin.")) {
    if(p.decoded.metaType().id()==QMetaType::QByteArray) fields[n]=QString::fromLatin1(p.decoded.toByteArray().toHex());
    else fields[n]=QJsonValue::fromVariant(p.decoded);
   }
  }
  objects.append(QJsonObject{{"object",double(o.handle)},{"class",o.avb?QString::fromLatin1(o.avb->classId):QString{}},{"complete",o.avb&&o.avb->interpretationComplete},{"identity",QString::fromLatin1(o.recordedIdentity.toHex())},{"fields",fields}});
 }
 for(const auto &m:result.mediaReferences) media.append(QJsonObject{{"object",double(m.objectKey.objectHandle)},{"id",QString::fromLatin1(m.mobId.toHex())},{"legacy",QString::fromLatin1(m.legacyId.toHex())}});
 for(const auto &i:result.issues) issues.append(QJsonObject{{"kind",int(i.kind)},{"object",double(i.objectKey.objectHandle)},{"field",i.propertyLocator.name},{"explanation",i.explanation}});
 for(const auto &s:index.sequences()) sequences.append(QJsonObject{{"object",double(s.key.objectHandle)},{"name",s.name},{"id",QString::fromLatin1(s.mobId.toHex())},{"userPlaced",s.userPlaced}});
 const QFileInfo after(args[1]); QJsonObject report{{"path",args[1]},{"bytes",double(before.size())},{"sizeAndMtimeUnchanged",before.size()==after.size()&&before.lastModified()==after.lastModified()},{"readerOutcome",int(source->outcome)},{"parsedObjects",double(source->objects.size())},{"parsedRelationships",double(source->relationships.size())},{"sequence",double(seq)},{"sequences",sequences},{"coverageComplete",result.coverageComplete},{"cancelled",result.cancelled},{"issues",issues},{"objects",objects},{"edges",edges},{"media",media}};
 QTextStream(stdout)<<QJsonDocument(report).toJson(QJsonDocument::Compact)<<'\n'; return 0;
}

import json,re,hashlib
from pathlib import Path
from collections import defaultdict,Counter,deque
root=Path('/tmp/mediamuster-copland-bin-technical-20261012')
r=json.loads((root/'production-graph.json').read_text())
objects={o['object']:o for o in r['objects']}; outgoing=defaultdict(list); media=defaultdict(set)
for e in r['edges']:outgoing[e['origin']].append(e)
for m in r['media']:
 if m['id']:media[m['object']].add(m['id'])
track_re=re.compile(r'TrackGroup.tracks\[(\d+)\].component$')
def fields(h):return objects[h]['fields']
def semantic(e):
 return e['field'].startswith(('TrackGroup.tracks[','Sequence.components[','SourceClip.mob_id','Composition.descriptor','Component.precomputed','MediaDescriptor.locators[','FileDescriptor.','AudioSuitePlugin.'))
def walk(start,selected=False,track=False):
 pending=[(start,None)];seen=set();ids=set()
 while pending:
  h,ctx=pending.pop()
  if (h,ctx) in seen:continue
  seen.add((h,ctx));ids.update(media[h]);o=objects[h];f=o['fields']
  for e in outgoing[h]:
   m=track_re.match(e['field'])
   if selected and o['class']=='SLCT' and m and int(m[1])!=f.get('Selector.selected'):continue
   if track and o['class']=='CMPO' and ctx and m:
    n=int(m[1]);component=objects[e['target']]
    if f.get(f'TrackGroup.tracks[{n}].index')!=ctx[0] or component['fields'].get('Component.media_kind_id')!=ctx[1]:continue
   newctx=None
   if track and o['class']=='SCLP' and e['field']=='SourceClip.mob_id':newctx=(f.get('SourceClip.track_id'),f.get('Component.media_kind_id'))
   pending.append((e['target'],newctx))
 return ids,seen
def brief(ids):
 return {'count':len(ids),'canonicalIdSetSha256':hashlib.sha256(b''.join(bytes.fromhex(x) for x in sorted(ids))).hexdigest(),'sampleIds':sorted(ids)[:4]}
def path(h):
 q=deque([r['sequence']]);prev={r['sequence']:None}
 while q:
  k=q.popleft()
  if k==h:break
  for e in outgoing[k]:
   if semantic(e) and e['target'] not in prev:prev[e['target']]=e;q.append(e['target'])
 if h not in prev:return None
 p=[]
 while prev[h]:e=prev[h];p.append(e);h=e['origin']
 return p[::-1]
def components(h):
 f=fields(h);result=[]
 for e in outgoing[h]:
  m=track_re.match(e['field'])
  if m:
   n=int(m[1]);result.append({'slot':n,'index':f.get(f'TrackGroup.tracks[{n}].index'),'component':e['target'],'mediaKindId':fields(e['target']).get('Component.media_kind_id'),'class':objects[e['target']]['class'],'flags':f.get(f'TrackGroup.tracks[{n}].flags')})
 return sorted(result,key=lambda t:t['slot'])
selectors=[];sources=[];renders=[]
for h,o in sorted(objects.items()):
 f=o['fields']
 if o['class']=='SLCT':
  branches=components(h);sets=[walk(t['component'])[0] for t in branches];selected=f['Selector.selected'];selectedids=sets[selected]
  restricted=[walk(t['component'],True,True)[0] for t in branches]
  for t,ids,usedids in zip(branches,sets,restricted):
   t['broadClosureIds']=brief(ids);t['idsOutsideSelectedClosure']=brief(ids-selectedids)
   t['diagnosticRestrictedClosureIds']=brief(usedids)
   t['diagnosticIdsOutsideSelectedClosure']=brief(usedids-restricted[selected])
  selectors.append({'object':h,'selected':selected,'length':f.get('TrackGroup.length'),'editRateMantissa':f.get('Component.edit_rate.mantissa'),'mediaKindId':f.get('Component.media_kind_id'),'pathFromSequence':path(h),'branches':branches})
 if o['class']=='SCLP':
  for e in outgoing[h]:
   if e['field']=='SourceClip.mob_id' and objects[e['target']]['class']=='CMPO':
    target=e['target'];branches=components(target)
    matching=[t for t in branches if t['index']==f.get('SourceClip.track_id') and t['mediaKindId']==f.get('Component.media_kind_id')]
    nonmatching=[t for t in branches if t not in matching]
    if matching and nonmatching:
     wanted=set().union(*(walk(t['component'])[0] for t in matching));unwanted=set().union(*(walk(t['component'])[0] for t in nonmatching))
     if unwanted-wanted:
      sources.append({'object':h,'kind':f.get('Component.media_kind_id'),'trackId':f.get('SourceClip.track_id'),'startTime':f.get('SourceClip.start_time'),'length':f.get('Clip.length'),'pathFromSequence':path(h),'target':target,'targetName':fields(target).get('Component.name'),'targetType':fields(target).get('Composition.mob_type'),'targetUsage':fields(target).get('Composition.usage_code'),'matchingTracks':matching,'nonmatchingTracks':nonmatching,'wantedBranchIds':brief(wanted),'otherTrackIdsOutsideWantedClosure':brief(unwanted-wanted)})
 for e in outgoing[h]:
  if e['field']=='Component.precomputed':
   rendered=walk(e['target'])[0];inputs=set()
   for t in outgoing[h]:
    if t['field'].startswith(('TrackGroup.tracks[','Sequence.components[')) and (t['field'].endswith('.component') or t['field'].startswith('Sequence.components[')):inputs.update(walk(t['target'])[0])
   if rendered and inputs and rendered-inputs:
    renders.append({'object':h,'class':o['class'],'precomputedObject':e['target'],'precomputedClass':objects[e['target']]['class'],'name':f.get('Component.name'),'length':f.get('TrackGroup.length',f.get('Clip.length')),'pathFromSequence':path(h),'inputIds':brief(inputs),'precomputedIds':brief(rendered),'precomputedIdsOutsideInputClosure':brief(rendered-inputs)})
current,_=walk(r['sequence']);selector_only,_=walk(r['sequence'],True,False);track_only,_=walk(r['sequence'],False,True);both,_=walk(r['sequence'],True,True)
# Diagnostic pruned traversals deliberately do not intersect requested time spans or establish effect semantics.
selectors.sort(key=lambda s:(s['pathFromSequence'] is None,not any(t['diagnosticIdsOutsideSelectedClosure']['count'] for t in s['branches']),s['selected']==0,min((len(s['pathFromSequence']) if s['pathFromSequence'] else 100),100),s['object']))
sources.sort(key=lambda s:(s['pathFromSequence'] is None,len(s['pathFromSequence']) if s['pathFromSequence'] else 100,s['targetType']!=2,s['object']))
renders.sort(key=lambda s:(s['pathFromSequence'] is None,len(s['pathFromSequence']) if s['pathFromSequence'] else 100,s['object']))
out={'reader':{k:v for k,v in r.items() if k not in ['objects','edges','media']},'reachableObjectCount':len(objects),'resolvedEdgeCount':len(r['edges']),'classCounts':dict(Counter(o['class'] for o in objects.values())),'selectorCount':len(selectors),'selectorSelectedCounts':dict(Counter(s['selected'] for s in selectors)),'sourceTrackExpansionCount':len(sources),'renderInputPairCount':len(renders),'productionMediaIds':brief(current),'diagnosticOnly':{'selectorPruned':brief(selector_only),'sourceTrackPruned':brief(track_only),'bothPruned':brief(both),'removedByBoth':brief(current-both),'limits':'Structural counterfactual only; not a proposed resolver or proof of playback membership. No requested time-span intersection, transitions, effect/timewarp semantics, attribute-route exclusion or Media Composer comparison.'},'selectorExamples':selectors[:6],'sourceTrackExamples':sources[:8],'renderExamples':renders[:8]}
(root/'structural-analysis.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps({k:v for k,v in out.items() if k not in ['selectorExamples','sourceTrackExamples','renderExamples']},indent=2))
for kind in ['selectorExamples','sourceTrackExamples','renderExamples']:
 print(kind,json.dumps(out[kind][:2],indent=2))

