before=path.stat()
def ident(o):return bytes(o.mob_id.bytes_le).hex() if hasattr(o,'mob_id') else None
def base(o):return {'object':o.instance_id,'class':o.class_id.decode(),'name':getattr(o,'name',None),'mediaKind':getattr(o,'media_kind',None),'mediaKindId':getattr(o,'media_kind_id',None),'length':getattr(o,'length',None),'editRate':getattr(o,'edit_rate',None),'mobId':ident(o)}
def track(t):return {'index':getattr(t,'index',None),'kind':t.media_kind,'component':t.component.instance_id if t.component else None,'class':t.component.class_id.decode() if t.component else None}
def used_routes(start):
 pending=[(start,None)];seen=set();clips=[];locators=[]
 while pending:
  o,ctx=pending.pop()
  if (o.instance_id,ctx) in seen:continue
  seen.add((o.instance_id,ctx))
  if len(seen)>200:raise RuntimeError('bounded route limit exceeded')
  if isinstance(o,SourceClip):
   target=o.mob;matched=o.track
   clips.append({**base(o),'trackId':o.track_id,'sourceStart':o.start_time,'target':base(target) if target else None,'matchedTrack':track(matched) if matched else None})
   if target:pending.append((target,(o.track_id,o.media_kind)))
  elif isinstance(o,Composition):
   desc=getattr(o,'descriptor',None);loc=getattr(desc,'locator',None) if desc else None
   if isinstance(loc,MSMLocator):locators.append({'sourceMob':o.instance_id,'sourceMobName':o.name,'sourceMobType':o.mob_type,'descriptorClass':desc.class_id.decode(),'descriptor':desc.instance_id,'locator':loc.instance_id,'fileMobId':ident(loc),'domainType':getattr(loc,'domain_type',None)})
   for t in o.tracks:
    if t.component and (ctx is None or (getattr(t,'index',None)==ctx[0] and t.media_kind==ctx[1])):pending.append((t.component,None))
  elif isinstance(o,Sequence):
   for c in o.components:pending.append((c,None))
  elif isinstance(o,Selector):
   pending.append((o.tracks[o.selected].component,None))
  elif hasattr(o,'tracks'):
   for t in o.tracks:
    if t.component:pending.append((t.component,None))
  pre=getattr(o,'precomputed',None)
  if pre:pending.append((pre,None))
 return {'visitedObjects':len(seen),'sourceClips':clips,'locators':locators,'uniqueFileMobIds':sorted({l['fileMobId'] for l in locators})}
